const $c=id=>document.getElementById(id);class ControlView{constructor(input){this.input=input;this.wheel=$c("ctl-wheel");this.rim=$c("ctl-rim");this.stick=$c("ctl-stick");this.knob=$c("ctl-knob");this.rev=$c("ctl-rev");this.hud=$c("hud");this.needLayout=true;this.lastA=null;this.lastK="";this.lastOn=null;const set=(on,e)=>{if(e){e.preventDefault();e.stopPropagation()}input.revHeld=on;this.rev.classList.toggle("down",on)};this.rev.style.touchAction="none";this.rev.addEventListener("pointerdown",e=>{try{this.rev.setPointerCapture(e.pointerId)}catch{}set(true,e)});for(const ev of["pointerup","pointercancel","lostpointercapture"])this.rev.addEventListener(ev,()=>set(false))}setMode(mode){this.wheel.hidden=mode!=="wheel";this.stick.hidden=mode!=="stick";this.rev.hidden=mode==="zones";this.rev.dataset.side=mode==="wheel"?"left":"right";this.rev.classList.remove("down");this.stick.classList.remove("on");this.lastOn=null;this.lastA=null;this.needLayout=true}layout(){const inp=this.input;const vw=window.innerWidth;const vh=window.innerHeight;inp.width=vw;const pad=this.hud.getBoundingClientRect();inp.bounds={l:0,t:0,r:vw,b:vh};if(pad.width){const cs=getComputedStyle(this.hud);inp.bounds={l:parseFloat(cs.getPropertyValue("--ctl-l"))||0,t:0,r:vw-(parseFloat(cs.getPropertyValue("--ctl-r"))||0),b:vh-(parseFloat(cs.getPropertyValue("--ctl-b"))||0)}}if(!this.wheel.hidden){const r=this.wheel.getBoundingClientRect();const cx=r.left+r.width/2;const cy=r.top+r.height/2;if(inp.wheelId!==null&&(Math.abs(cx-inp.wheel.cx)>.5||Math.abs(cy-inp.wheel.cy)>.5))inp.wheelHole=true;inp.wheel.cx=cx;inp.wheel.cy=cy;inp.wheel.r=r.width/2}this.needLayout=false}update(){if(this.hud.hidden){this.needLayout=true;return}if(this.needLayout)this.layout();const inp=this.input;if(inp.mode==="wheel"){const a=Math.round(inp.wheelS*200)/200;if(a!==this.lastA){this.lastA=a;this.rim.style.transform=`rotate(${a}rad)`}}else if(inp.mode==="stick"){const s=inp.stick;if(s.on!==this.lastOn){this.lastOn=s.on;this.stick.classList.toggle("on",s.on)}if(s.on){const k=`${s.x},${s.y},${Math.round(s.dx)},${Math.round(s.dy*.4)}`;if(k!==this.lastK){this.lastK=k;this.stick.style.transform=`translate(${s.x}px,${s.y}px)`;this.knob.style.transform=`translate(${Math.round(s.dx)}px,${Math.round(s.dy*.4)}px)`}}}}}export{ControlView};
